function akhir<T>(a: T[]): T | undefined {
  return a[a.length - 1];
}
console.log(akhir(["kopi", "teh"]));

function petakan<T, U>(a: T[], f: (x: T) => U): U[] {
  return a.map(f);
}
console.log(petakan([1, 2], (n) => n * 2));

function p<T extends { length: number }>(x: T) {
  return x.length;
}
console.log(p(12345));

function ambil<T, K extends keyof T>(o: T, k: K): T[K] {
  return o[k];
}
console.log(ambil({ nama: "Kopi", harga: 18000 }, "harga"));

type R<T> = { ok: true; data: T } | { ok: false; pesan: string };
function cari(): R<number> {
  return { ok: false, pesan: "tidak ada" };
}
const r = cari();
console.log(r.ok ? r.data : "gagal: " + r.pesan);

class Antrian<T> {
  private isi: T[] = [];
  masuk(x: T) {
    this.isi.push(x);
  }
  keluar() {
    return this.isi.shift();
  }
  get n() {
    return this.isi.length;
  }
}
const q = new Antrian<string>();
q.masuk("a");
q.masuk("b");
console.log(q.keluar());
console.log(q.n);

